import { canRead, canEdit, type MemberRole } from "./policy";
export type Project = {
  id: string;
  title: string;
  members: Record<string, MemberRole>;
};
export class ProjectPermissionError extends Error {
  constructor() {
    super("Forbidden");
    this.name = "ProjectPermissionError";
  }
}
export function readProject(project: Project, userId: string) {
  if (!canRead(project.members[userId])) throw new ProjectPermissionError();
  return { id: project.id, title: project.title };
}
export function updateProject(project: Project, userId: string, title: string) {
  if (!canEdit(project.members[userId])) throw new ProjectPermissionError();
  project.title = title;
  return readProject(project, userId);
}

import { describe, expect, it, vi } from "vitest";
import { renderToStaticMarkup } from "react-dom/server";
import ProjectsPage from "../app/projects/page";
import { GET, PATCH } from "../app/api/projects/route";
import { ProjectEditor } from "../components/ProjectEditor";
import { canEdit, canRead } from "../features/sharing/policy";
import * as sharing from "../features/sharing/service";

const project = (): sharing.Project => ({
  id: "one",
  title: "Original",
  members: { alice: "owner", bob: "editor", charlie: "viewer" },
});

function patchRequest(body: unknown) {
  return new Request("http://fixture.invalid/api/projects", {
    method: "PATCH",
    headers: { "content-type": "application/json" },
    body: JSON.stringify(body),
  });
}

describe("project sharing permissions", () => {
  it.each([
    { role: "owner", readable: true, editable: true },
    { role: "editor", readable: true, editable: true },
    { role: "viewer", readable: true, editable: false },
    { role: undefined, readable: false, editable: false },
  ] as const)("applies the read/edit policy for $role", ({ role, readable, editable }) => {
    expect(canRead(role)).toBe(readable);
    expect(canEdit(role)).toBe(editable);
  });

  it("keeps the complete project unchanged after a viewer update is denied", () => {
    const current = project();
    const before = structuredClone(current);
    expect(sharing.readProject(current, "charlie")).toEqual({
      id: "one",
      title: "Original",
    });
    expect(() => sharing.updateProject(current, "charlie", "Forbidden change"))
      .toThrow(sharing.ProjectPermissionError);
    expect(current).toEqual(before);
  });

  it.each(["owner", "editor"] as const)(
    "does not reuse a different project's %s role",
    (role) => {
      const editable: sharing.Project = {
        id: "editable",
        title: "Editable",
        members: { user: role },
      };
      const readOnly: sharing.Project = {
        id: "read-only",
        title: "Read only",
        members: { user: "viewer" },
      };
      const unrelated = project();
      const before = structuredClone([readOnly, unrelated]);

      expect(sharing.updateProject(editable, "user", "Edited").title).toBe("Edited");
      expect(sharing.readProject(readOnly, "user").title).toBe("Read only");
      expect(() => sharing.updateProject(readOnly, "user", "Forbidden change"))
        .toThrow(sharing.ProjectPermissionError);
      expect(() => sharing.readProject(unrelated, "user"))
        .toThrow(sharing.ProjectPermissionError);
      expect(() => sharing.updateProject(unrelated, "user", "Forbidden change"))
        .toThrow(sharing.ProjectPermissionError);
      expect([readOnly, unrelated]).toEqual(before);
    },
  );

  it("checks the current project membership on every update", () => {
    const current = project();
    sharing.updateProject(current, "bob", "Allowed");
    current.members.bob = "viewer";
    const before = structuredClone(current);

    expect(() => sharing.updateProject(current, "bob", "Forbidden change"))
      .toThrow(sharing.ProjectPermissionError);
    expect(current).toEqual(before);
    expect(sharing.readProject(current, "bob").title).toBe("Allowed");
  });

  it("renders the real projects page with viewer content and disabled edit controls", () => {
    const html = renderToStaticMarkup(<ProjectsPage />);
    expect(html).toContain("공유 프로젝트");
    expect(html).toContain("읽기 전용");
    expect(html).toMatch(/<input\b[^>]*\bdisabled=""/);
    expect(html).toMatch(/<button\b[^>]*\bdisabled=""/);
  });

  it.each(["owner", "editor"] as const)(
    "keeps %s controls enabled without a read-only notice",
    (role) => {
      const html = renderToStaticMarkup(<ProjectEditor role={role} title="Editable" />);
      expect(html).toContain("Editable");
      expect(html).toMatch(/<input\b/);
      expect(html).toMatch(/<button\b/);
      expect(html).not.toContain("disabled");
      expect(html).not.toContain("읽기 전용");
    },
  );
});

describe("project API permission responses", () => {
  it.each([
    { title: "Forbidden change" },
    { title: "Forbidden change", userId: "alice", role: "owner", projectId: "other" },
    { title: "Forbidden change", userId: "bob", role: "editor" },
  ])("rejects viewer writes without trusting payload permissions: %j", async (body) => {
    const before = await GET().json();
    const response = await PATCH(patchRequest(body));

    expect(response.status).toBe(403);
    expect(await response.text()).toBe("Forbidden");
    const after = GET();
    expect(after.status).toBe(200);
    expect(await after.json()).toEqual(before);
  });

  it.each([{}, { title: 42 }, { title: null }])(
    "preserves invalid-title validation and project data: %j",
    async (body) => {
      const before = await GET().json();
      const response = await PATCH(patchRequest(body));
      expect(response.status).toBe(400);
      expect(await response.text()).toBe("Invalid title");
      expect(await GET().json()).toEqual(before);
    },
  );

  it("does not disguise unrelated service failures as permission errors", async () => {
    const failure = new Error("Unexpected failure");
    const update = vi.spyOn(sharing, "updateProject").mockImplementationOnce(() => {
      throw failure;
    });
    try {
      await expect(PATCH(patchRequest({ title: "Edited" }))).rejects.toBe(failure);
    } finally {
      update.mockRestore();
    }
  });
});
